// 標準入力（左の「入力例」の内容）を 1 つの文字列として受け取り、
// 改行で区切って 1 行ずつの配列にする
const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

// 入力例 1 のとき:
//   input[0] は "3"
//   input[1] は "abcxyz"

// 答えは console.log で出力する
// ここに解答を書く

solution.code:
import { readFileSync } from "fs";

const [first, s] = readFileSync(0, "utf8").trim().split("\n");
// 26 回ずらすと元に戻るので、K は 26 で割った余りだけ考えればよい
const k = Number(first) % 26;

let out = "";
for (const c of s) {
  const code = (c.charCodeAt(0) - 97 + k) % 26;
  out += String.fromCharCode(97 + code);
}
console.log(out);
